import React, { useEffect, useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { CheckCircle2, Eye, EyeOff, GraduationCap, Lock, Shield, ShoppingBag, User } from "lucide-react";
import { useAuth } from "./AuthContext";
import { useNotice } from "./NoticeContext";
import { decodeJwtPayload } from "./authJwt";
import { h } from "./h";
import { apiFetch } from "./api";
import { apiErrorMessage } from "./screensAuth";
import { Button, Field, InlineNotice, OtpCodeInput, TextInput } from "./ui";

function sessionRole(data) {
  const r = data?.user?.role;
  if (r) return r;
  return decodeJwtPayload(data?.accessToken)?.role || "";
}

function AdminBrandingColumn() {
  return h(
    "div",
    {
      key: "brand",
      className:
        "relative flex flex-col justify-between overflow-hidden bg-[#0b1220] px-5 py-6 text-white sm:px-6 md:w-[44%] md:shrink-0 md:py-7"
    },
    [
      h("div", {
        key: "dots-tl",
        className:
          "pointer-events-none absolute -left-6 -top-6 h-28 w-28 rounded-full bg-emerald-500/15 blur-2xl"
      }),
      h("div", {
        key: "dots-br",
        className:
          "pointer-events-none absolute -bottom-8 -right-8 h-32 w-32 rounded-full bg-emerald-400/10 blur-2xl"
      }),
      h("div", { key: "top", className: "relative z-10 flex items-center gap-2.5" }, [
        h(
          "div",
          {
            key: "ico",
            className:
              "flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-gradient-to-br from-emerald-400 to-green-600 shadow-md shadow-emerald-900/50"
          },
          h(ShoppingBag, { className: "h-5 w-5 text-white" })
        ),
        h("div", { key: "titles", className: "min-w-0" }, [
          h("div", { key: "t1", className: "font-display text-base font-bold tracking-tight sm:text-lg" }, "CampusMarket"),
          h(
            "div",
            { key: "t2", className: "text-[10px] font-medium uppercase tracking-wider text-emerald-300/90 sm:text-xs" },
            "Admin Portal"
          )
        ])
      ]),
      h("div", { key: "mid", className: "relative z-10 mt-5 md:mt-4" }, [
        h("div", { key: "grad", className: "mb-1.5 flex items-center gap-1.5 text-emerald-400" }, [
          h(GraduationCap, { className: "h-4 w-4 shrink-0" }),
          h("span", { className: "text-xs font-semibold" }, "Staff only")
        ]),
        h(
          "h1",
          { key: "h1", className: "font-display text-xl font-bold leading-snug sm:text-2xl" },
          "Admin Access Only"
        ),
        h(
          "p",
          { key: "sub", className: "mt-2 text-xs leading-relaxed text-slate-300 sm:text-sm" },
          "Secure login for administrators to manage the CampusMarket platform."
        )
      ]),
      h(
        "div",
        {
          key: "illus",
          className: "relative z-10 mt-5 hidden items-end justify-center gap-2 md:flex"
        },
        [
          h(
            "div",
            {
              key: "lap",
              className:
                "relative rounded-xl border border-white/10 bg-slate-800/50 p-2.5 shadow-lg backdrop-blur-sm"
            },
            [
              h("div", { className: "mb-1.5 h-1.5 w-20 rounded bg-white/20" }),
              h("div", { className: "mb-1.5 h-1.5 w-16 rounded bg-white/10" }),
              h("div", { className: "h-12 w-28 rounded-md bg-emerald-500/20" })
            ]
          ),
          h(
            "div",
            {
              key: "shield",
              className:
                "-ml-4 flex h-[4.5rem] w-[4.5rem] shrink-0 items-center justify-center rounded-2xl border-[3px] border-emerald-400/80 bg-emerald-500/20 shadow-lg"
            },
            h(Shield, { className: "h-9 w-9 text-emerald-300" })
          )
        ]
      )
    ]
  );
}

/** Single centered card: dark brand panel + form panel (does not stretch to full viewport). */
function AdminAuthCardLayout({ children }) {
  return h(
    "div",
    {
      className:
        "min-h-screen bg-slate-100 py-8 dark:bg-night-950 sm:flex sm:items-center sm:justify-center sm:py-10"
    },
    h(
      "div",
      { className: "mx-auto w-full max-w-lg px-4 sm:max-w-3xl sm:px-5" },
      h(
        "div",
        {
          className:
            "flex flex-col overflow-hidden rounded-3xl border border-slate-200/90 bg-white shadow-2xl dark:border-white/10 dark:bg-night-900 md:flex-row"
        },
        [
          h(AdminBrandingColumn, { key: "left" }),
          h(
            "div",
            { key: "right", className: "min-h-0 min-w-0 flex-1 bg-white p-5 sm:p-6 dark:bg-night-900" },
            children
          )
        ]
      )
    )
  );
}

export function AdminLoginPage() {
  const nav = useNavigate();
  const { login, logout, accessToken, user, loading } = useAuth();
  const { toast } = useNotice();
  const [identifier, setIdentifier] = useState("");
  const [password, setPassword] = useState("");
  const [show, setShow] = useState(false);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    if (!loading && accessToken && user?.role === "admin") {
      nav("/admin", { replace: true });
    }
  }, [loading, accessToken, user, nav]);

  const onSubmit = async (e) => {
    e.preventDefault();
    setErr("");
    setBusy(true);
    try {
      const data = await login(identifier.trim(), password);
      if (data?.needsOtp) {
        nav("/admin/login-otp", {
          replace: true,
          state: { email: data.email || identifier.trim().toLowerCase(), from: "/admin" }
        });
        return;
      }
      if (sessionRole(data) !== "admin") {
        await logout();
        setErr("This portal is for platform administrators only. Use the main sign-in for buyer or vendor accounts.");
        return;
      }
      toast("Welcome — admin dashboard", { variant: "success" });
      nav("/admin", { replace: true });
    } catch (ex) {
      const msg = apiErrorMessage(ex, "We couldn’t sign you in. Check your email and password.");
      if (ex.status === 403 && /verify/i.test(msg)) {
        setErr("This account must verify email on the main site first, or contact support.");
      } else {
        setErr(msg);
      }
    } finally {
      setBusy(false);
    }
  };

  return h(
    AdminAuthCardLayout,
    { key: "page" },
    [
      h("div", { key: "hdr", className: "mb-5 text-center" }, [
        h(
          "div",
          {
            key: "shico",
            className:
              "mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-2xl bg-emerald-500/15 text-emerald-600 dark:text-emerald-400"
          },
          h(Shield, { className: "h-6 w-6" })
        ),
        h("h2", { key: "t", className: "font-display text-xl font-bold text-slate-900 dark:text-white sm:text-2xl" }, "Admin Login"),
        h(
          "p",
          { key: "s", className: "mt-1.5 text-xs text-slate-600 dark:text-slate-400 sm:text-sm" },
          "Enter your credentials to access the admin dashboard."
        )
      ]),
      h(
        "form",
        { key: "frm", className: "space-y-3 sm:space-y-4", onSubmit },
        [
          h(Field, { key: "em", label: "Email Address" }, h("div", { className: "relative" }, [
            h(User, {
              className: "pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400"
            }),
            h(TextInput, {
              type: "email",
              autoComplete: "username",
              value: identifier,
              onChange: (e) => setIdentifier(e.target.value),
              placeholder: "Enter admin email",
              className: "pl-10",
              required: true
            })
          ])),
          h(Field, { key: "pw", label: "Password" }, h("div", { className: "relative" }, [
            h(Lock, {
              className: "pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400"
            }),
            h(TextInput, {
              type: show ? "text" : "password",
              autoComplete: "current-password",
              value: password,
              onChange: (e) => setPassword(e.target.value),
              placeholder: "Enter password",
              className: "pr-12 pl-10",
              required: true
            }),
            h(
              "button",
              {
                key: "eye",
                type: "button",
                className:
                  "tap-target absolute right-1 top-1/2 -translate-y-1/2 rounded-xl p-2 text-slate-500 hover:bg-slate-100 dark:text-slate-400 dark:hover:bg-white/10",
                onClick: () => setShow((s) => !s)
              },
              show ? h(EyeOff, { className: "h-5 w-5" }) : h(Eye, { className: "h-5 w-5" })
            )
          ])),
          err ? h(InlineNotice, { key: "err", variant: "error", onDismiss: () => setErr("") }, err) : null,
          h(
            Button,
            {
              key: "go",
              type: "submit",
              className: "w-full !bg-emerald-600 !text-white hover:!bg-emerald-700 dark:!bg-emerald-600",
              loading: busy
            },
            "Login to Dashboard"
          )
        ]
      ),
      h("div", { key: "div", className: "relative my-5" }, [
        h("div", { className: "absolute inset-0 flex items-center" }, h("div", { className: "w-full border-t border-slate-200 dark:border-white/10" })),
        h(
          "div",
          { className: "relative flex justify-center text-[10px] font-semibold uppercase tracking-wide sm:text-xs" },
          h(
            "span",
            {
              className:
                "inline-flex items-center gap-1.5 bg-white px-2 text-emerald-600 dark:bg-night-900 dark:text-emerald-400 sm:px-3"
            },
            [h(CheckCircle2, { className: "h-3.5 w-3.5" }), "Secure"]
          )
        )
      ]),
      h(
        "div",
        {
          key: "note",
          className:
            "flex gap-2.5 rounded-2xl border border-emerald-200/80 bg-emerald-50/80 p-3 text-xs text-emerald-900 dark:border-emerald-500/30 dark:bg-emerald-500/10 dark:text-emerald-100/90 sm:gap-3 sm:p-4 sm:text-sm"
        },
        [
          h(Lock, { className: "mt-0.5 h-4 w-4 shrink-0" }),
          h("p", { key: "txt" }, [
            h("span", { className: "font-semibold" }, "Restricted Access"),
            " — This area is for authorized administrators only. There is no self-service registration."
          ])
        ]
      ),
      h(
        "p",
        { key: "back", className: "mt-5 text-center text-xs text-slate-500 dark:text-slate-400 sm:text-sm" },
        h(Link, { to: "/", className: "text-emerald-600 hover:underline dark:text-emerald-400" }, "← Back to CampusMarket")
      )
    ]
  );
}

export function AdminLoginOtpPage() {
  const nav = useNavigate();
  const location = useLocation();
  const { verifyLoginOtp, logout, accessToken, user, loading } = useAuth();
  const { toast } = useNotice();
  const email = String(location.state?.email || "").trim().toLowerCase();
  const [otp, setOtp] = useState("");
  const [password, setPassword] = useState("");
  const [showPw, setShowPw] = useState(false);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);
  const [resendLoading, setResendLoading] = useState(false);
  const [resendMsg, setResendMsg] = useState("");

  useEffect(() => {
    if (!loading && accessToken && user?.role === "admin") {
      nav("/admin", { replace: true });
    }
  }, [loading, accessToken, user, nav]);

  useEffect(() => {
    if (!email) nav("/admin/login", { replace: true });
  }, [email, nav]);

  const onSubmit = async (e) => {
    e.preventDefault();
    setErr("");
    setResendMsg("");
    if (otp.length !== 6) {
      setErr("Enter the full 6-digit code.");
      return;
    }
    setBusy(true);
    try {
      const data = await verifyLoginOtp(email, otp);
      if (sessionRole(data) !== "admin") {
        await logout();
        setErr("This portal is for platform administrators only.");
        return;
      }
      toast("Welcome — admin dashboard", { variant: "success" });
      nav("/admin", { replace: true });
    } catch (ex) {
      setErr(apiErrorMessage(ex, "That code did not work. Try again or request a new code."));
    } finally {
      setBusy(false);
    }
  };

  const onResend = async (e) => {
    e.preventDefault();
    setErr("");
    setResendMsg("");
    if (!password) {
      setErr("Enter your password to send a new code.");
      return;
    }
    setResendLoading(true);
    try {
      await apiFetch("/api/auth/resend-login-otp", {
        method: "POST",
        json: { identifier: email, password }
      });
      setResendMsg("A new code was sent to your email.");
      setOtp("");
    } catch (ex) {
      setErr(apiErrorMessage(ex, "Could not resend. Check your password and try again."));
    } finally {
      setResendLoading(false);
    }
  };

  if (!email) return null;

  return h(
    AdminAuthCardLayout,
    { key: "page" },
    [
      h("div", { key: "hdr", className: "mb-5 text-center" }, [
        h("h2", { key: "t", className: "font-display text-xl font-bold text-slate-900 dark:text-white sm:text-2xl" }, "Verify sign-in"),
        h(
          "p",
          { key: "s", className: "mt-1.5 break-all text-xs text-slate-600 dark:text-slate-400 sm:text-sm" },
          `We sent a 6-digit code to ${email}.`
        )
      ]),
      h(
        "form",
        { key: "frm", className: "space-y-3 sm:space-y-4", onSubmit },
        [
          h(
            Field,
            { key: "otp", label: "Sign-in code" },
            h(OtpCodeInput, {
              value: otp,
              onChange: setOtp,
              autoFocus: true,
              "aria-invalid": err && otp.length < 6 ? true : undefined
            })
          ),
          err ? h(InlineNotice, { key: "err", variant: "error", onDismiss: () => setErr("") }, err) : null,
          resendMsg
            ? h(InlineNotice, { key: "ok", variant: "success", size: "sm", onDismiss: () => setResendMsg("") }, resendMsg)
            : null,
          h(
            Button,
            {
              key: "go",
              type: "submit",
              className: "w-full !bg-emerald-600 !text-white hover:!bg-emerald-700",
              loading: busy
            },
            "Continue to dashboard"
          ),
          h("div", { key: "resend", className: "rounded-2xl border border-slate-200/80 bg-slate-50 p-3 dark:border-white/10 dark:bg-white/5 sm:p-4" }, [
            h("p", { key: "r1", className: "text-[10px] font-semibold uppercase tracking-wide text-slate-500 sm:text-xs" }, "Need a new code?"),
            h(Field, { key: "pw", label: "Password" }, h("div", { className: "relative" }, [
              h(TextInput, {
                type: showPw ? "text" : "password",
                autoComplete: "current-password",
                value: password,
                onChange: (e) => setPassword(e.target.value),
                className: "pr-12",
                placeholder: "••••••••"
              }),
              h(
                "button",
                {
                  key: "eye",
                  type: "button",
                  className:
                    "tap-target absolute right-1 top-1/2 -translate-y-1/2 rounded-xl p-2 text-slate-500 hover:bg-white/40 dark:hover:bg-white/10",
                  onClick: () => setShowPw((s) => !s)
                },
                showPw ? h(EyeOff, { className: "h-5 w-5" }) : h(Eye, { className: "h-5 w-5" })
              )
            ])),
            h(
              Button,
              {
                key: "rs",
                type: "button",
                variant: "subtle",
                className: "mt-3 w-full",
                loading: resendLoading,
                onClick: onResend
              },
              "Resend code"
            )
          ]),
          h(
            Link,
            {
              key: "back",
              to: "/admin/login",
              className: "block text-center text-xs text-emerald-600 hover:underline dark:text-emerald-400 sm:text-sm"
            },
            "← Back to admin sign in"
          )
        ]
      )
    ]
  );
}
